from backend import Duplicate

class Store:
    def __init__(self, backend):
        self.backend = backend
    def put(self, key, value):
        try:
            self.backend.put(key, value)
        except Duplicate:
            return False
        return True
class Duplicate(Exception):
    pass

class Backend:
    def __init__(self):
        self.rows = {}
    def put(self, key, value):
        if key in self.rows:
            raise Duplicate(key)
        self.rows[key] = value
